//! The app's configuration (`app_config.rs`, since 0.24.0): `config/app.yaml` and its profiles,
//! what `fsp gen` writes from them, what it refuses, how a build picks its profile, and (with
//! `dart` on PATH) that the generated file compiles, picks the profile the define names and stops
//! a build whose define names none.

use std::fs;
use std::path::Path;

use crate::app_config::{
    self, Active, check_profile, defined_in, emit, load, task_vars, with_define,
};
use crate::config::Config;
use crate::session::Session;

fn write(root: &Path, rel: &str, body: &str) {
    let p = root.join(rel);
    fs::create_dir_all(p.parent().unwrap()).unwrap();
    fs::write(p, body).unwrap();
}

/// A project with one page and the given files.
fn project(files: &[(&str, &str)]) -> tempfile::TempDir {
    let dir = tempfile::tempdir().unwrap();
    write(dir.path(), "pubspec.yaml", "name: demo\n");
    write(
        dir.path(),
        "lib/app/page.dart",
        "class HomePage extends StatelessWidget { const HomePage({super.key}); }",
    );
    for (rel, body) in files {
        write(dir.path(), rel, body);
    }
    dir
}

/// The diagnostics of `config/` for `files`, one line each (`✗ config/app.yaml:3  ...`).
fn diags(files: &[(&str, &str)]) -> Vec<String> {
    let dir = project(files);
    load(dir.path(), "lib/app.config.g.dart")
        .diags
        .0
        .iter()
        .map(ToString::to_string)
        .collect()
}

/// The generated file for `files`, which must have no errors.
fn generated(files: &[(&str, &str)]) -> String {
    let dir = project(files);
    let loaded = load(dir.path(), "lib/app.config.g.dart");
    assert!(!loaded.diags.has_errors(), "{:?}", loaded.diags);
    emit(loaded.config.as_ref().expect("a configuration"))
}

const BASE: &str = "\
# The app's name, on the splash.
app_name: Shop
api:
  # The API every call goes to.
  #
  # No trailing slash.
  base_url: https://api.example.com
  timeout_ms: 8000
  retry_ratio: 1
sentry_dsn: null
new_checkout: false
hosts: [api.example.com]
";

const DEV: &str = "\
api:
  base_url: http://localhost:8080
  retry_ratio: 0.5
new_checkout: true
hosts: [localhost, 10.0.2.2]
";

const STAGING: &str = "\
api:
  base_url: https://staging.example.com
sentry_dsn: https://abc@o1.ingest.sentry.io/2
";

fn shop() -> Vec<(&'static str, &'static str)> {
    vec![
        ("config/app.yaml", BASE),
        ("config/app.dev.yaml", DEV),
        ("config/app.staging.yaml", STAGING),
    ]
}

/// The whole file, for the configuration above: the header, the choice of the profile, the check
/// of `FSP_PROFILE`, and one constant per value, documented by the comment above its key. It is
/// what `dart format` writes (a constant on one line when it fits).
const SHOP_DART: &str = r"// GENERATED by fsp from config/: edit config/app.yaml, config/app.dev.yaml and config/app.staging.yaml, not this file.
// Every value here is compiled into the app, where anyone who has the app can read it: never a
// secret (docs/app-config.md).
// ignore_for_file: type=lint, unused_element

const String _requested = String.fromEnvironment('FSP_PROFILE');
const String _flavor = String.fromEnvironment('FLUTTER_APP_FLAVOR');
const bool _debug =
    !bool.fromEnvironment('dart.vm.product') &&
    !bool.fromEnvironment('dart.vm.profile');

/// The active profile: FSP_PROFILE (`fsp dev --profile`, `fsp build --profile`), else the
/// flavour (`--flavor`) when a profile has its name, else `dev` in a debug build when there is
/// a `dev` profile, else `default`.
const String _profile = bool.hasEnvironment('FSP_PROFILE')
    ? (_requested == '' ? 'default' : _requested)
    : _flavor == 'dev' || _flavor == 'staging'
    ? _flavor
    : _debug
    ? 'dev'
    : 'default';

/// A build whose FSP_PROFILE names no profile of config/ stops here, since dividing by zero is an
/// error in a constant. The profiles: `default`, `dev`, `staging`.
const int _fspProfileNamesNoFileOfConfig =
    1 ~/
    (_profile == 'default' || _profile == 'dev' || _profile == 'staging'
        ? 1
        : 0);

/// The values of config/app.yaml, with those of the active profile over them.
abstract final class AppConfig {
  /// The active profile: `default` (config/app.yaml alone), `dev` or `staging`.
  static const String profile = _profile;

  /// The app's name, on the splash.
  ///
  /// `app_name` in config/app.yaml.
  static const String appName = 'Shop';

  /// The API every call goes to.
  ///
  /// No trailing slash.
  ///
  /// `api.base_url` in config/app.yaml; set by `dev` and `staging`.
  static const String apiBaseUrl = _profile == 'dev'
      ? 'http://localhost:8080'
      : _profile == 'staging'
      ? 'https://staging.example.com'
      : 'https://api.example.com';

  /// `api.timeout_ms` in config/app.yaml.
  static const int apiTimeoutMs = 8000;

  /// `api.retry_ratio` in config/app.yaml; set by `dev`.
  static const double apiRetryRatio = _profile == 'dev' ? 0.5 : 1.0;

  /// `sentry_dsn` in config/app.yaml; set by `staging`.
  static const String? sentryDsn = _profile == 'staging'
      ? 'https://abc@o1.ingest.sentry.io/2'
      : null;

  /// `new_checkout` in config/app.yaml; set by `dev`.
  static const bool newCheckout = _profile == 'dev' ? true : false;

  /// `hosts` in config/app.yaml; set by `dev`.
  static const List<String> hosts = _profile == 'dev'
      ? ['localhost', '10.0.2.2']
      : ['api.example.com'];
}
";

#[test]
fn the_shop_configuration_makes_this_file() {
    assert_eq!(generated(&shop()), SHOP_DART);
}

#[test]
fn no_config_folder_is_no_configuration() {
    let dir = project(&[]);
    let loaded = load(dir.path(), "lib/app.config.g.dart");
    assert!(!loaded.on);
    assert!(loaded.config.is_none());
    assert!(loaded.diags.0.is_empty());
    // A folder of other files is not one either.
    let dir = project(&[
        ("config/README.md", "# ours\n"),
        ("config/ci.yaml", "a: 1\n"),
    ]);
    assert!(!load(dir.path(), "lib/app.config.g.dart").on);
}

#[test]
fn app_yaml_alone_has_only_the_default_profile() {
    let code = generated(&[("config/app.yaml", "title: Shop\n")]);
    assert!(code.contains(
        "const String _profile = bool.hasEnvironment('FSP_PROFILE')\n    ? (_requested == '' ? 'default' : _requested)\n    : 'default';\n"
    ));
    assert!(code.contains("1 ~/ (_profile == 'default' ? 1 : 0);"));
    assert!(code.contains("static const String title = 'Shop';"));
    assert!(!code.contains("_flavor"));
    assert!(!code.contains("_debug"));
}

#[test]
fn a_debug_build_has_dev_only_when_there_is_a_dev_profile() {
    let code = generated(&[
        ("config/app.yaml", "title: Shop\n"),
        ("config/app.staging.yaml", "title: Shop (staging)\n"),
    ]);
    assert!(code.contains("    : _flavor == 'staging'\n    ? _flavor\n    : 'default';\n"));
    assert!(!code.contains("_debug"));
}

#[test]
fn strings_are_escaped_and_ints_in_a_double_get_a_point() {
    let code = generated(&[(
        "config/app.yaml",
        "greeting: \"It's $5 \\\\ a\\nb\"\nratio: 2\nratios: [1, 0.5]\nbig: 9007199254740992\n",
    )]);
    assert!(code.contains(r"static const String greeting = 'It\'s \$5 \\ a\nb';"));
    assert!(code.contains("static const int ratio = 2;"));
    assert!(code.contains("static const List<double> ratios = [1.0, 0.5];"));
    assert!(code.contains("static const int big = 9007199254740992;"));
}

#[test]
fn a_profile_changes_only_keys_app_yaml_has() {
    assert_eq!(
        diags(&[
            ("config/app.yaml", "api:\n  base_url: https://a\n"),
            ("config/app.dev.yaml", "api:\n  base_ur: http://b\n"),
        ]),
        [
            "✗ config/app.dev.yaml:2  `api.base_ur` is not in config/app.yaml: a profile only changes values that config/app.yaml has (a typo?)"
        ]
    );
    assert_eq!(
        diags(&[
            ("config/app.yaml", "api:\n  base_url: https://a\n"),
            ("config/app.dev.yaml", "api: http://b\n"),
        ]),
        [
            "✗ config/app.dev.yaml:1  `api` is a map in config/app.yaml: config/app.dev.yaml can change the values in it, not replace it"
        ]
    );
    assert_eq!(
        diags(&[
            ("config/app.yaml", "api: https://a\n"),
            ("config/app.dev.yaml", "api:\n  base_url: http://b\n"),
        ]),
        ["✗ config/app.dev.yaml:1  `api` is a value in config/app.yaml, not a map"]
    );
}

#[test]
fn a_key_has_one_type_in_every_file() {
    assert_eq!(
        diags(&[
            ("config/app.yaml", "timeout: 30\n"),
            ("config/app.dev.yaml", "timeout: \"30s\"\n"),
        ]),
        [
            "✗ config/app.dev.yaml:1  `timeout` is a number in config/app.yaml and a string in config/app.dev.yaml: a key has one type in every file"
        ]
    );
    assert_eq!(
        diags(&[("config/app.yaml", "hosts: [a, 1]\n")]),
        ["✗ config/app.yaml:1  `hosts` holds a string and a number: a list holds one type"]
    );
    assert_eq!(
        diags(&[("config/app.yaml", "hosts: [[a]]\n")]),
        [
            "✗ config/app.yaml:1  `hosts` is a list of lists: a list holds strings, numbers or booleans"
        ]
    );
}

#[test]
fn null_and_empty_lists_take_their_type_from_another_file() {
    let code = generated(&[
        ("config/app.yaml", "dsn: null\nhosts: []\n"),
        ("config/app.prod.yaml", "dsn: https://x\nhosts: [a]\n"),
    ]);
    assert!(code.contains("static const String? dsn = _profile == 'prod'"));
    assert!(code.contains("static const List<String> hosts = _profile == 'prod' ? ['a'] : [];"));
    assert_eq!(
        diags(&[("config/app.yaml", "dsn: null\n")]),
        [
            "✗ config/app.yaml:1  `dsn` is null in config/app.yaml and in every profile, so fsp cannot tell its type: give it a value in one of them"
        ]
    );
    assert_eq!(
        diags(&[("config/app.yaml", "hosts: []\n")]),
        [
            "✗ config/app.yaml:1  `hosts` is an empty list in every file, so fsp cannot tell what it holds: give it a value in one of them"
        ]
    );
}

#[test]
fn profile_files_are_checked_by_their_names() {
    assert_eq!(
        diags(&[
            ("config/app.yaml", "a: 1\n"),
            ("config/app.release.yaml", "a: 2\n")
        ]),
        [
            "✗ config/app.release.yaml  `release` is a Flutter build mode (`flutter run --release`), not a profile: rename config/app.release.yaml"
        ]
    );
    assert_eq!(
        diags(&[
            ("config/app.yaml", "a: 1\n"),
            ("config/app.default.yaml", "a: 2\n")
        ]),
        [
            "✗ config/app.default.yaml  `default` is the name of config/app.yaml alone, not of a profile: rename config/app.default.yaml"
        ]
    );
    assert_eq!(
        diags(&[
            ("config/app.yaml", "a: 1\n"),
            ("config/app.a.b.yaml", "a: 2\n")
        ]),
        [
            "✗ config/app.a.b.yaml  `a.b` is not a profile name: use letters, digits, `_` and `-`, starting with a letter (config/app.<profile>.yaml)"
        ]
    );
    assert_eq!(
        diags(&[("config/app.yml", "a: 1\n")]),
        [
            "✗ config/app.yml  fsp reads `.yaml` files in config/: rename config/app.yml to config/app.yaml"
        ]
    );
    assert_eq!(
        diags(&[("config/app.dev.yaml", "a: 1\n")]),
        [
            "✗ config/app.dev.yaml  config/app.dev.yaml is a profile of config/app.yaml, which is missing: a profile changes values that config/app.yaml has"
        ]
    );
}

#[test]
fn keys_make_names_that_must_not_clash() {
    assert_eq!(
        diags(&[("config/app.yaml", "api_url: a\napi:\n  url: b\n")]),
        [
            "✗ config/app.yaml:3  `api.url` and `api_url` would both be the constant AppConfig.apiUrl: rename one"
        ]
    );
    assert_eq!(
        diags(&[("config/app.yaml", "default: a\n")]),
        [
            "✗ config/app.yaml:1  `default` would be the constant AppConfig.default, and `default` is a reserved word in Dart: rename the key"
        ]
    );
    assert_eq!(
        diags(&[("config/app.yaml", "profile: a\n")]),
        [
            "✗ config/app.yaml:1  `profile` would be the constant AppConfig.profile, which is the name of the active profile: rename the key"
        ]
    );
    assert_eq!(
        diags(&[("config/app.yaml", "2fa: true\n")]),
        [
            "✗ config/app.yaml:1  `2fa` is not a key fsp can name: a key is letters, digits, `_` and `-`, starting with a letter"
        ]
    );
    // camelCase, snake_case and kebab-case keys all make a lowerCamelCase constant.
    let code = generated(&[(
        "config/app.yaml",
        "oidc:\n  clientId: a\n  redirect-uri: b\n  scope_list: [c]\n",
    )]);
    assert!(code.contains("static const String oidcClientId = 'a';"));
    assert!(code.contains("static const String oidcRedirectUri = 'b';"));
    assert!(code.contains("static const List<String> oidcScopeList = ['c'];"));
}

#[test]
fn a_file_that_is_no_map_or_no_yaml_is_an_error() {
    assert_eq!(
        diags(&[("config/app.yaml", "")]),
        [
            "✗ config/app.yaml  config/app.yaml has no values: write `key: value` lines, which `fsp gen` turns into the constants of AppConfig"
        ]
    );
    assert_eq!(
        diags(&[("config/app.yaml", "- a\n")]),
        [
            "✗ config/app.yaml  config/app.yaml must be a map of keys to values (`api_url: https://...`)"
        ]
    );
    let bad = diags(&[("config/app.yaml", "a: [1\n")]);
    assert_eq!(bad.len(), 1);
    assert!(bad[0].starts_with("✗ config/app.yaml:"), "{bad:?}");
    assert!(
        bad[0].contains("config/app.yaml is not YAML that fsp can read: "),
        "{bad:?}"
    );
    // An empty profile changes nothing, and is a profile.
    let code = generated(&[("config/app.yaml", "a: 1\n"), ("config/app.prod.yaml", "")]);
    assert!(code.contains("_flavor == 'prod'"));
}

#[test]
fn a_credential_is_an_error_and_a_secret_name_a_warning() {
    // Built at run time, so the fake key is no literal a secret scanner stops a push for.
    let stripe = format!("stripe:\n  key: sk_{}_aB3dE5gH7jK9mN1pQ2rS4tU6\n", "live");
    assert_eq!(
        diags(&[("config/app.yaml", stripe.as_str())]),
        [
            "✗ config/app.yaml:2  `stripe.key` in config/app.yaml looks like a Stripe secret key: every value in config/ is compiled into the app, where anyone who has the app can read it; keep the secret on a server and give the app only what it may show (docs/app-config.md, \"Secrets\")"
        ]
    );
    assert_eq!(
        diags(&[
            ("config/app.yaml", "db: https://example.com\n"),
            (
                "config/app.dev.yaml",
                "db: postgres://app:hunter2@localhost/app\n"
            ),
        ]),
        [
            "✗ config/app.dev.yaml:1  `db` in config/app.dev.yaml looks like a URL with a password in it: every value in config/ is compiled into the app, where anyone who has the app can read it; keep the secret on a server and give the app only what it may show (docs/app-config.md, \"Secrets\")"
        ]
    );
    assert_eq!(
        diags(&[(
            "config/app.yaml",
            "oauth:\n  client_secret: abc123\n  password_min: 8\n"
        )]),
        [
            "! config/app.yaml:2  `oauth.client_secret` in config/app.yaml is named like a secret: every value in config/ is compiled into the app, where anyone who has the app can read it; if it is a secret, keep it on a server (docs/app-config.md, \"Secrets\"), and if it is not, give it a name that says so"
        ]
    );
    // An empty value named like a secret says nothing: there is nothing in it yet.
    assert!(diags(&[("config/app.yaml", "client_secret: ''\n")]).is_empty());
    // A warning does not stop the file.
    let dir = project(&[("config/app.yaml", "password: abc\n")]);
    assert!(load(dir.path(), "lib/app.config.g.dart").config.is_some());
}

#[test]
fn gen_writes_the_configuration_beside_the_output_and_fails_on_its_errors() {
    let dir = project(&[("config/app.yaml", "title: Shop\n")]);
    let cfg = Config::load(dir.path()).unwrap();
    let mut session = Session::default();
    let out = crate::gen_core(dir.path(), &cfg, true, &mut session, |_, _| {}).unwrap();
    assert_eq!(out.output, "lib/app.g.dart, lib/app.config.g.dart");
    assert_eq!(
        session.config_written.as_deref(),
        Some("lib/app.config.g.dart")
    );
    let written = fs::read_to_string(dir.path().join("lib/app.config.g.dart")).unwrap();
    assert!(written.contains("static const String title = 'Shop';"));
    // Unchanged: nothing written, and the pass says so.
    let out = crate::gen_core(dir.path(), &cfg, true, &mut session, |_, _| {}).unwrap();
    assert!(!out.wrote);
    assert_eq!(session.config_written, None);
    // An error in config/ fails gen and leaves every file as it was.
    write(dir.path(), "config/app.dev.yaml", "titel: x\n");
    let err =
        crate::gen_core(dir.path(), &cfg, true, &mut Session::default(), |_, _| {}).unwrap_err();
    assert_eq!(
        format!("{err:#}"),
        "1 error(s); lib/app.g.dart and lib/app.config.g.dart left unchanged"
    );
    assert_eq!(
        fs::read_to_string(dir.path().join("lib/app.config.g.dart")).unwrap(),
        written
    );
    // `output:` elsewhere moves it too.
    let dir = project(&[
        ("config/app.yaml", "title: Shop\n"),
        (
            "pubspec.yaml",
            "name: demo\nfespalier:\n  output: lib/router/routes.g.dart\n",
        ),
    ]);
    let cfg = Config::load(dir.path()).unwrap();
    assert_eq!(cfg.output_config(), "lib/router/routes.config.g.dart");
    crate::gen_core(dir.path(), &cfg, true, &mut Session::default(), |_, _| {}).unwrap();
    assert!(dir.path().join("lib/router/routes.config.g.dart").is_file());
}

#[test]
fn a_file_left_from_a_config_that_is_gone_is_a_warning() {
    let dir = project(&[(
        "lib/app.config.g.dart",
        "// GENERATED by fsp from config/: edit config/app.yaml, not this file.\n",
    )]);
    let loaded = load(dir.path(), "lib/app.config.g.dart");
    assert_eq!(
        loaded
            .diags
            .0
            .iter()
            .map(ToString::to_string)
            .collect::<Vec<_>>(),
        [
            "! lib/app.config.g.dart  lib/app.config.g.dart was generated from config/app.yaml, which is gone: delete lib/app.config.g.dart, or put config/app.yaml back"
        ]
    );
    // A file of that name that fsp did not write is not ours to talk about.
    let dir = project(&[("lib/app.config.g.dart", "// mine\n")]);
    assert!(load(dir.path(), "lib/app.config.g.dart").diags.0.is_empty());
}

fn args(words: &[&str]) -> Vec<String> {
    words.iter().map(|w| (*w).to_string()).collect()
}

#[test]
fn the_active_profile_is_the_define_then_the_flavour_then_the_build_mode() {
    let profiles = args(&["dev", "prod", "staging"]);
    let active = |explicit: Option<&str>, a: &[&str], default_flavor: Option<&str>, debug: bool| {
        app_config::active(explicit, &args(a), default_flavor, &profiles, debug)
    };
    let is = |name: &str, why: &'static str| Active {
        name: name.to_string(),
        why,
    };
    assert_eq!(
        active(Some("staging"), &["--flavor", "prod"], None, true),
        is("staging", "FSP_PROFILE")
    );
    assert_eq!(
        active(Some(""), &[], None, true),
        is("default", "FSP_PROFILE")
    );
    assert_eq!(
        active(None, &["--flavor", "prod"], None, true),
        is("prod", "the flavour")
    );
    assert_eq!(
        active(None, &["--flavor=prod"], None, false),
        is("prod", "the flavour")
    );
    assert_eq!(
        active(None, &[], Some("staging"), true),
        is("staging", "the flavour")
    );
    // A flavour that no profile is named after is not one.
    assert_eq!(
        active(None, &["--flavor", "free"], None, true),
        is("dev", "a debug build")
    );
    assert_eq!(active(None, &[], None, false), is("default", ""));
    let no_dev = app_config::active(None, &[], None, &args(&["prod"]), true);
    assert_eq!(no_dev, is("default", ""));
    assert_eq!(
        is("staging", "FSP_PROFILE").line(),
        "profile staging (FSP_PROFILE): config/app.staging.yaml over config/app.yaml"
    );
    assert_eq!(is("default", "").line(), "profile default: config/app.yaml");
    assert!(app_config::run_is_debug(&args(&["-d", "chrome"])));
    assert!(!app_config::run_is_debug(&args(&["--release"])));
    assert!(!app_config::run_is_debug(&args(&["--profile"])));
    assert!(!app_config::build_is_debug(&args(&["--release"])));
    assert!(app_config::build_is_debug(&args(&["--debug"])));
}

#[test]
fn a_profile_flag_must_name_a_file_of_config() {
    let dir = project(&[
        ("config/app.yaml", "a: 1\n"),
        ("config/app.dev.yaml", "a: 2\n"),
    ]);
    assert!(check_profile(dir.path(), "dev").is_ok());
    assert!(check_profile(dir.path(), "default").is_ok());
    assert_eq!(
        format!("{:#}", check_profile(dir.path(), "stagng").unwrap_err()),
        "`--profile stagng`: there is no config/app.stagng.yaml; the profiles are default, dev"
    );
    assert_eq!(
        format!("{:#}", check_profile(dir.path(), "release").unwrap_err()),
        "`--profile release` names a profile of config/, and `release` is a Flutter build mode: pass that to flutter after `--` (`-- --release`)"
    );
    let none = project(&[]);
    assert_eq!(
        format!("{:#}", check_profile(none.path(), "dev").unwrap_err()),
        "`--profile dev`: this app has no config/app.yaml, so it has no profiles (docs/app-config.md)"
    );
}

#[test]
fn the_profile_goes_to_flutter_as_a_define_in_front_of_the_arguments() {
    assert_eq!(
        with_define(Some("staging"), &args(&["-d", "chrome"])).unwrap(),
        args(&["--dart-define=FSP_PROFILE=staging", "-d", "chrome"])
    );
    assert_eq!(
        with_define(None, &args(&["-d", "x"])).unwrap(),
        args(&["-d", "x"])
    );
    assert_eq!(
        format!(
            "{:#}",
            with_define(Some("staging"), &args(&["--dart-define=FSP_PROFILE=dev"])).unwrap_err()
        ),
        "`--profile staging` and `--dart-define=FSP_PROFILE=dev` after `--` both name the profile: keep one"
    );
    assert_eq!(
        defined_in(&args(&[
            "--dart-define",
            "FSP_PROFILE=dev",
            "--dart-define=X=1"
        ])),
        Some("dev".to_string())
    );
    assert_eq!(defined_in(&args(&["--dart-define=X=1"])), None);
}

#[test]
fn a_change_in_config_wakes_the_watcher_and_its_other_files_do_not() {
    use notify::event::{CreateKind, DataChange, ModifyKind};
    use notify::{Event, EventKind};
    let root = Path::new("/p");
    let config = root.join("config");
    let app = root.join("lib/app");
    let outputs = vec![
        root.join("lib/app.g.dart"),
        root.join("lib/app.config.g.dart"),
    ];
    let ev = |p: &str| {
        Event::new(EventKind::Modify(ModifyKind::Data(DataChange::Content))).add_path(root.join(p))
    };
    let wakes = |e: &Event| crate::watch::relevant(e, &outputs, &app, &config);
    assert!(wakes(&ev("config/app.yaml")));
    assert!(wakes(&ev("config/app.staging.yaml")));
    assert!(wakes(&ev("config/app.yml")));
    assert!(!wakes(&ev("config/README.md")));
    assert!(!wakes(&ev("config/sub")));
    assert!(wakes(
        &Event::new(EventKind::Create(CreateKind::Folder)).add_path(config.clone())
    ));
    // Writing the generated file does not wake it again.
    assert!(!wakes(&ev("lib/app.config.g.dart")));
    assert!(wakes(&ev("lib/app/page.dart")));
}

/// The dart program that prints what the generated file chose.
const PROBE: &str = "import '../lib/app.config.g.dart';\n\nvoid main() {\n  print('${AppConfig.profile} ${AppConfig.apiBaseUrl} ${AppConfig.newCheckout}');\n  if (AppConfig.newCheckout) print('NEW-CHECKOUT-CODE');\n}\n";

/// `dart` with `args` in `dir`: its stdout, or its stderr when it failed. `None` without dart.
fn dart(dir: &Path, args: &[&str]) -> Option<Result<String, String>> {
    let bin = std::env::var("FSP_DART").unwrap_or_else(|_| "dart".into());
    let out = std::process::Command::new(bin)
        .args(args)
        .current_dir(dir)
        .output()
        .ok()?;
    let text = |b: &[u8]| String::from_utf8_lossy(b).into_owned();
    Some(if out.status.success() {
        Ok(text(&out.stdout))
    } else {
        Err(format!("{}{}", text(&out.stdout), text(&out.stderr)))
    })
}

#[test]
fn the_generated_file_compiles_and_picks_the_profile_the_build_names() {
    let dir = tempfile::tempdir().unwrap();
    let root = dir.path();
    write(
        root,
        "pubspec.yaml",
        "name: probe\nenvironment:\n  sdk: ^3.9.0\n",
    );
    write(root, "lib/app.config.g.dart", &generated(&shop()));
    write(root, "bin/main.dart", PROBE);
    let Some(analyzed) = dart(root, &["analyze", "--fatal-infos", "--fatal-warnings"]) else {
        let required = std::env::var("FSP_REQUIRE_DART").is_ok_and(|v| v == "1");
        assert!(
            !required,
            "dart is required (FSP_REQUIRE_DART=1) and is not on PATH"
        );
        return;
    };
    assert!(analyzed.is_ok(), "{analyzed:?}");
    let run = |defines: &[&str]| {
        let mut a = vec!["run"];
        a.extend(defines);
        a.push("bin/main.dart");
        dart(root, &a).unwrap()
    };
    // `dart run` is a debug build: `dev`.
    assert_eq!(
        run(&[]).unwrap(),
        "dev http://localhost:8080 true\nNEW-CHECKOUT-CODE\n"
    );
    assert_eq!(
        run(&["-DFSP_PROFILE=staging"]).unwrap(),
        "staging https://staging.example.com false\n"
    );
    assert_eq!(
        run(&["-DFSP_PROFILE="]).unwrap(),
        "default https://api.example.com false\n"
    );
    assert_eq!(
        run(&["-DFLUTTER_APP_FLAVOR=staging"]).unwrap(),
        "staging https://staging.example.com false\n"
    );
    // A flavour no profile is named after leaves the choice to the build mode.
    assert_eq!(
        run(&["-DFLUTTER_APP_FLAVOR=free"]).unwrap(),
        "dev http://localhost:8080 true\nNEW-CHECKOUT-CODE\n"
    );
    // A release build: `default`.
    assert_eq!(
        run(&["-Ddart.vm.product=true"]).unwrap(),
        "default https://api.example.com false\n"
    );
    // A profile that is not there stops the build, on the line that says why.
    let stopped = run(&["-DFSP_PROFILE=stagng"]).unwrap_err();
    assert!(
        stopped.contains("_fspProfileNamesNoFileOfConfig"),
        "{stopped}"
    );
    // A release build to JavaScript holds its own profile's values and none of the others, nor
    // the code behind a flag that is off.
    let js = root.join("out.js");
    let js_arg = format!("-o{}", js.display());
    let compiled = dart(
        root,
        &[
            "compile",
            "js",
            "-O2",
            "-Ddart.vm.product=true",
            &js_arg,
            "bin/main.dart",
        ],
    )
    .unwrap();
    assert!(compiled.is_ok(), "{compiled:?}");
    let out = fs::read_to_string(&js).unwrap();
    assert!(out.contains("https://api.example.com"));
    for absent in ["localhost:8080", "staging.example.com", "NEW-CHECKOUT-CODE"] {
        assert!(!out.contains(absent), "{absent} is in the release build");
    }
}

#[test]
fn profiles_are_in_the_order_of_their_names() {
    let dir = project(&[
        ("config/app.yaml", "issuer: ''\n"),
        ("config/app.keycloak-dpop.yaml", "issuer: k\n"),
        ("config/app.keycloak.yaml", "issuer: k\n"),
    ]);
    let config = load(dir.path(), "lib/app.config.g.dart").config.unwrap();
    assert_eq!(config.profiles, ["keycloak", "keycloak-dpop"]);
    assert_eq!(
        app_config::profile_names(dir.path()).unwrap(),
        ["keycloak", "keycloak-dpop"]
    );
}

#[test]
fn the_task_commands_get_the_values_of_their_profile() {
    let dir = project(&shop());
    let config = load(dir.path(), "lib/app.config.g.dart").config.unwrap();
    let vars = |name: &str| -> Vec<String> {
        task_vars(&config, name)
            .into_iter()
            .map(|(k, v)| format!("{k}={v}"))
            .collect()
    };
    assert_eq!(
        vars("dev"),
        [
            "FSP_CONFIG_APP_NAME=Shop",
            "FSP_CONFIG_API_BASE_URL=http://localhost:8080",
            "FSP_CONFIG_API_TIMEOUT_MS=8000",
            "FSP_CONFIG_API_RETRY_RATIO=0.5",
            "FSP_CONFIG_NEW_CHECKOUT=true",
            r#"FSP_CONFIG_HOSTS=["localhost","10.0.2.2"]"#,
        ]
    );
    // A null value is no variable; a value no profile changes is app.yaml's.
    assert_eq!(
        vars("staging"),
        [
            "FSP_CONFIG_APP_NAME=Shop",
            "FSP_CONFIG_API_BASE_URL=https://staging.example.com",
            "FSP_CONFIG_API_TIMEOUT_MS=8000",
            "FSP_CONFIG_API_RETRY_RATIO=1.0",
            "FSP_CONFIG_SENTRY_DSN=https://abc@o1.ingest.sentry.io/2",
            "FSP_CONFIG_NEW_CHECKOUT=false",
            r#"FSP_CONFIG_HOSTS=["api.example.com"]"#,
        ]
    );
    assert_eq!(vars("default"), vars("no-such-profile"));
    // Two constants that are one variable.
    assert_eq!(
        diags(&[("config/app.yaml", "apiURL: a\napi_url: b\n")]),
        [
            "✗ config/app.yaml:2  `api_url` and `apiURL` would both be the variable FSP_CONFIG_API_URL of the task's commands: rename one"
        ]
    );
}
